<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{Booking,StayLifecycleEvent}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class StayLifecycleController extends Controller {public function update(Request $r,Booking $booking,string $action){abort_unless(in_array($action,['check-in','reverse-check-in','check-out','no-show']),404);$data=$r->validate(['reason'=>['nullable','string','max:1000']]);try{DB::transaction(function()use($r,$booking,$action,$data){$now=now();match($action){'check-in'=>$booking->update(['checked_in_at'=>$now,'status'=>'checked_in']),'reverse-check-in'=>$booking->update(['checked_in_at'=>null,'check_in_reversed_at'=>$now,'status'=>'confirmed']),'check-out'=>$booking->update(['checked_out_at'=>$now,'completed_at'=>$now,'status'=>'completed']),'no-show'=>$booking->update(['no_show_at'=>$now,'status'=>'no_show'])};StayLifecycleEvent::create(['booking_id'=>$booking->id,'actor_id'=>$r->user()->id,'event'=>str_replace('-','_',$action),'note'=>$data['reason']??null,'viewer_timezone'=>$r->user()->timezone,'operational_timezone'=>config('azari.timezone','Africa/Lagos'),'ip_address'=>$r->ip(),'user_agent'=>substr((string)$r->userAgent(),0,1000)]);});return back()->with('success','Booking lifecycle updated.');}catch(\Throwable $e){report($e);return back()->with('error','The booking lifecycle could not be updated.');}}}
